557	  /** How many distinct names each segment appears in — the rarity signal that
558	   *  separates a discriminative word ("checkout") from a ubiquitous one ("state"). */
559	  getSegmentNameCounts(segments: string[]): Map<string, number> {
560	    if (segments.length === 0) return new Map();
