710	  /**
711	   * Find the file that holds the densest concentration of the project's
712	   * internal call graph — the "core" file. Used by context-builder to
713	   * boost ranking of symbols in that file's directory (so e.g. sinatra
714	   * queries surface `lib/sinatra/base.rb`'s `route!` instead of
715	   * `sinatra-contrib/lib/sinatra/multi_route.rb`'s `route` extension).
716	   *
717	   * Returns null if no file has a meaningful concentration (e.g. spread
718	   * evenly across many files, or empty index).
719	   *
720	   * "Internal" = source and target are in the same file. Cross-file
721	   * edges aren't useful here — they don't tell us which file is the
722	   * functional center.
723	   *
724	   * Excludes test/spec files from candidacy via path-pattern. The agent's
725	   * typical question is "how does X work", not "how is X tested", so
726	   * boosting a test file's directory would be a misfire.
727	   */
728	  getDominantFile(): { filePath: string; edgeCount: number; nextEdgeCount: number } | null {
729	    if (!this.stmts.getDominantFile) {
730	      // Pull top 20 candidates; we then filter out test/generated files
731	      // in code (regex-grade matching that SQL LIKE can't express). The
732	      // generated-file filter is critical — without it, etcd's
733	      // `api/etcdserverpb/rpc.pb.go` (1916 in-file edges, generated
734	      // protobuf stub) outranks the real `server/etcdserver/server.go`
735	      // (470 edges) by 4×, and the boost would push the agent toward
736	      // generated code.
737	      this.stmts.getDominantFile = this.db.prepare(`
738	        SELECT n.file_path AS file_path, COUNT(*) AS edge_count
739	        FROM edges e
740	        JOIN nodes n ON e.source = n.id
741	        JOIN nodes m ON e.target = m.id
742	        WHERE n.file_path = m.file_path
743	        GROUP BY n.file_path
744	        ORDER BY edge_count DESC
745	        LIMIT 20
746	      `);
747	    }
748	    const rows = this.stmts.getDominantFile.all() as Array<{ file_path: string; edge_count: number }>;
749	    const filtered = rows.filter(r => !isLowValueFile(r.file_path));
750	    if (filtered.length === 0 || filtered[0]!.edge_count < 20) return null;
751	    return {
752	      filePath: filtered[0]!.file_path,
753	      edgeCount: filtered[0]!.edge_count,
754	      nextEdgeCount: filtered[1]?.edge_count ?? 0,
755	    };
756	  }
757	
758	  /**
759	   * Find the file that holds the densest concentration of the project's
760	   * `route` nodes (framework-emitted: Express/Gin/Flask/Rails/Drupal/etc.).
761	   * Used by handleContext on small repos to inline the project's routing
762	   * config when the agent's query is about request flow — eliminating the
763	   * "Glob + Read routes.rb" pattern that beats codegraph on tiny realworld
764	   * template repos.
765	   *
766	   * Excludes test/generated files from candidacy. Returns null if there
767	   * are fewer than 3 non-test routes total, or if no file holds at least
768	   * 30% of them (diffuse routing → no single answer file).
769	   */
770	  getTopRouteFile(): { filePath: string; routeCount: number; totalRoutes: number } | null {
771	    if (!this.stmts.getTopRouteFile) {
772	      this.stmts.getTopRouteFile = this.db.prepare(`
773	        SELECT file_path, COUNT(*) AS cnt
774	        FROM nodes
775	        WHERE kind = 'route'
776	        GROUP BY file_path
777	        ORDER BY cnt DESC
778	        LIMIT 20
779	      `);
780	    }
781	    const rows = this.stmts.getTopRouteFile.all() as Array<{ file_path: string; cnt: number }>;
782	    const filtered = rows.filter(r => !isLowValueFile(r.file_path));
783	    if (filtered.length === 0) return null;
784	    const totalRoutes = filtered.reduce((sum, r) => sum + r.cnt, 0);
785	    const top = filtered[0]!;
786	    if (totalRoutes < 3 || top.cnt < 3) return null;
787	    if (top.cnt / totalRoutes < 0.30) return null;
788	    return { filePath: top.file_path, routeCount: top.cnt, totalRoutes };
789	  }
