791	  /**
792	   * Build a URL → handler manifest from the index. Each route node's
793	   * `references` edge points at the function/method that handles the
794	   * request. We join them in one pass; the agent gets the canonical
795	   * routing answer ("POST /users/login → AuthController#login") without
796	   * having to parse the framework's route DSL itself.
797	   *
798	   * Also returns the file with the most handler endpoints — used as the
799	   * "top handler file" to inline source for, so the agent has both the
800	   * mapping AND the handler implementations.
801	   */
802	  getRoutingManifest(limit: number = 40): {
803	    entries: Array<{ url: string; handler: string; handlerFile: string; handlerLine: number; handlerKind: string }>;
804	    topHandlerFile: string | null;
805	    topHandlerFileCount: number;
806	    totalRoutes: number;
807	  } | null {
808	    if (!this.stmts.getRoutingManifest) {
809	      // Edge kind varies across framework resolvers: Spring/Rails/
810	      // Laravel/Drupal emit `references`, Express emits `calls`. Accept
811	      // both — the semantic is the same (route → its handler).
812	      this.stmts.getRoutingManifest = this.db.prepare(`
813	        SELECT
814	          r.name AS url,
815	          h.name AS handler,
816	          h.file_path AS handler_file,
817	          h.start_line AS handler_line,
818	          h.kind AS handler_kind
819	        FROM nodes r
820	        JOIN edges e ON e.source = r.id
821	        JOIN nodes h ON e.target = h.id
822	        WHERE r.kind = 'route'
823	          AND e.kind IN ('references', 'calls')
824	          AND h.kind IN ('function', 'method', 'class')
825	        ORDER BY r.file_path, r.start_line
826	        LIMIT ?
827	      `);
828	    }
829	    const rows = this.stmts.getRoutingManifest.all(limit) as Array<{
830	      url: string; handler: string; handler_file: string; handler_line: number; handler_kind: string;
831	    }>;
832	    // Drop test/generated handlers — same hygiene as elsewhere.
833	    const filtered = rows.filter(r => !isLowValueFile(r.handler_file));
834	    if (filtered.length < 3) return null;
835	    // Identify the file holding the most handlers (the "primary handler file").
836	    const fileCounts = new Map<string, number>();
837	    for (const r of filtered) {
838	      fileCounts.set(r.handler_file, (fileCounts.get(r.handler_file) ?? 0) + 1);
839	    }
840	    let topHandlerFile: string | null = null;
841	    let topHandlerFileCount = 0;
842	    for (const [file, count] of fileCounts) {
843	      if (count > topHandlerFileCount) {
844	        topHandlerFile = file;
845	        topHandlerFileCount = count;
846	      }
847	    }
848	    return {
849	      entries: filtered.map(r => ({
850	        url: r.url,
851	        handler: r.handler,
852	        handlerFile: r.handler_file,
853	        handlerLine: r.handler_line,
854	        handlerKind: r.handler_kind,
855	      })),
856	      topHandlerFile,
857	      topHandlerFileCount,
858	      totalRoutes: filtered.length,
859	    };
860	  }
