874	   * Stream every node of a kind one at a time (lazy) instead of materializing
875	   * them all like {@link getNodesByKind}. For unbounded kinds (`function`,
876	   * `method`) on a symbol-dense project the full array is gigabytes; the
877	   * dynamic-edge synthesizers only scan-and-filter, so they iterate to keep
878	   * memory O(1) in the node count rather than O(nodes) (#610).
879	   */
880	  *iterateNodesByKind(kind: NodeKind): IterableIterator<Node> {
881	    // Fresh statement per call (not a cached one): an iterator holds an open
882	    // cursor, so a shared statement would conflict across overlapping scans.
883	    const stmt = this.db.prepare('SELECT * FROM nodes WHERE kind = ?');
884	    for (const row of stmt.iterate(kind)) {
885	      yield rowToNode(row as NodeRow);
886	    }
