979	  /**
980	   * Search nodes by name using FTS with fallback to LIKE for better matching
981	   *
982	   * Search strategy:
983	   * 1. Try FTS5 prefix match (query*) for word-start matching
984	   * 2. If no results, try LIKE for substring matching (e.g., "signIn" finds "signInWithGoogle")
985	   * 3. Score results based on match quality
986	   */
987	  searchNodes(query: string, options: SearchOptions = {}): SearchResult[] {
988	    const { limit = 100, offset = 0 } = options;
989	
990	    // Parse field-qualified bits out of the raw query (kind:, lang:,
991	    // path:, name:). Anything not recognised stays in `text` and goes
992	    // to FTS unchanged. Filters compose with the SearchOptions arg —
993	    // both are applied (intersection-style).
994	    const parsed = parseQuery(query);
995	    const mergedKinds =
996	      parsed.kinds.length > 0
997	        ? Array.from(new Set([...(options.kinds ?? []), ...parsed.kinds]))
998	        : options.kinds;
999	    const mergedLanguages =
1000	      parsed.languages.length > 0
1001	        ? Array.from(new Set([...(options.languages ?? []), ...parsed.languages]))
1002	        : options.languages;
1003	    const pathFilters = parsed.pathFilters;
1004	    const nameFilters = parsed.nameFilters;
1005	    // The text portion drives FTS/LIKE; if all the user typed was
1006	    // filters (`kind:function`), we still need *some* candidate set,
1007	    // so synthesise an empty-text path that returns everything matching
1008	    // the filters.
1009	    const text = parsed.text;
1010	    const kinds = mergedKinds;
1011	    const languages = mergedLanguages;
1012	
1013	    // First try FTS5 with prefix matching
1014	    let results = text
1015	      ? this.searchNodesFTS(text, { kinds, languages, limit, offset })
1016	      // Over-fetch by 5× when running filter-only (no text). The
1017	      // post-scoring path: + name: filters can be very selective, so
1018	      // a smaller multiplier risks returning fewer than `limit`
1019	      // results despite the DB having plenty of matches.
1020	      : this.searchAllByFilters({ kinds, languages, limit: limit * 5 });
1021	
1022	    // If no FTS results, try LIKE-based substring search
1023	    if (results.length === 0 && text.length >= 2) {
1024	      results = this.searchNodesLike(text, { kinds, languages, limit, offset });
1025	    }
1026	
1027	    // Final fuzzy fallback: scan all known names and keep those within
1028	    // a tight Levenshtein distance. Only fires when both FTS and LIKE
1029	    // returned nothing AND there's a text portion long enough to be
1030	    // worth fuzzing (1-char queries would match too much).
1031	    if (results.length === 0 && text.length >= 3) {
1032	      results = this.searchNodesFuzzy(text, { kinds, languages, limit });
1033	    }
1034	
1035	    // Supplement: ensure exact name matches are always candidates.
1036	    // BM25 can bury short exact-match names (e.g. "getBean") under hundreds of
1037	    // compound names (e.g. "getBeanDescriptor") in large codebases,
1038	    // pushing them past the FTS fetch limit before post-hoc scoring can help.
1039	    // Use the max BM25 score as the base so the nameMatchBonus (exact=30 vs
1040	    // prefix=20) actually differentiates them after rescoring.
1041	    if (results.length > 0 && query) {
1042	      const existingIds = new Set(results.map(r => r.node.id));
1043	      const maxFtsScore = Math.max(...results.map(r => r.score));
1044	      const terms = query.split(/\s+/).filter(t => t.length >= 2);
1045	      for (const term of terms) {
1046	        let sql = 'SELECT * FROM nodes WHERE name = ? COLLATE NOCASE';
1047	        const params: (string | number)[] = [term];
1048	        if (kinds && kinds.length > 0) {
1049	          sql += ` AND kind IN (${kinds.map(() => '?').join(',')})`;
1050	          params.push(...kinds);
1051	        }
1052	        if (languages && languages.length > 0) {
1053	          sql += ` AND language IN (${languages.map(() => '?').join(',')})`;
1054	          params.push(...languages);
1055	        }
1056	        sql += ' LIMIT 20';
1057	        const rows = this.db.prepare(sql).all(...params) as NodeRow[];
1058	        for (const row of rows) {
1059	          if (!existingIds.has(row.id)) {
1060	            results.push({ node: rowToNode(row), score: maxFtsScore });
1061	            existingIds.add(row.id);
1062	          }
1063	        }
1064	      }
1065	    }
1066	
1067	    // Apply multi-signal scoring
1068	    if (results.length > 0 && (text || query)) {
1069	      const scoringQuery = text || query;
1070	      results = results.map(r => ({
1071	        ...r,
1072	        score: r.score
1073	          + kindBonus(r.node.kind)
1074	          + scorePathRelevance(r.node.filePath, scoringQuery, this.projectNameTokens)
1075	          + nameMatchBonus(r.node.name, scoringQuery),
1076	      }));
1077	      results.sort((a, b) => b.score - a.score);
1078	      // Trim to requested limit after rescoring
1079	      if (results.length > limit) {
1080	        results = results.slice(0, limit);
1081	      }
1082	    }
1083	
1084	    // Apply path: + name: filters AFTER scoring. Scoring already uses
1085	    // path/name as a soft signal; the explicit filters here are a hard
1086	    // gate. Done last so the FTS limit fetched plenty of candidates to
1087	    // narrow from.
1088	    if (pathFilters.length > 0) {
1089	      const lowered = pathFilters.map((p) => p.toLowerCase());
1090	      results = results.filter((r) => {
1091	        const fp = r.node.filePath.toLowerCase();
1092	        return lowered.some((p) => fp.includes(p));
1093	      });
1094	    }
1095	    if (nameFilters.length > 0) {
1096	      const lowered = nameFilters.map((n) => n.toLowerCase());
1097	      results = results.filter((r) => {
1098	        const nm = r.node.name.toLowerCase();
1099	        return lowered.some((n) => nm.includes(n));
1100	      });
1101	    }
1102	
1103	    return results;
1104	  }
