1134	  /**
1135	   * Fuzzy fallback: when zero FTS/LIKE hits, try an edit-distance
1136	   * sweep over the distinct symbol-name set. Caps `maxDist` at 2 so
1137	   * `getUssr` finds `getUser` but `process` doesn't match `prosody`.
1138	   * Bounded edit distance keeps each comparison cheap; the per-query
1139	   * scan is O(distinct-name-count) which is far smaller than total
1140	   * node count on any real codebase.
1141	   */
1142	  private searchNodesFuzzy(
1143	    text: string,
1144	    options: { kinds?: NodeKind[]; languages?: Language[]; limit: number }
1145	  ): SearchResult[] {
1146	    const { kinds, languages, limit } = options;
1147	    const lowered = text.toLowerCase();
1148	    const maxDist = lowered.length <= 4 ? 1 : 2;
1149	
1150	    // Pull the distinct name list once. The set is cached on QueryBuilder
1151	    // by getAllNodeNames(); even on a 200k-node project the distinct
1152	    // name set is typically O(10k) because most names repeat. The
1153	    // candidate-cap below bounds memory regardless.
1154	    const allNames = this.getAllNodeNames();
1155	    const candidates: Array<{ name: string; dist: number }> = [];
1156	    for (const name of allNames) {
1157	      const dist = boundedEditDistance(name.toLowerCase(), lowered, maxDist);
1158	      if (dist <= maxDist) candidates.push({ name, dist });
1159	    }
1160	    candidates.sort((a, b) => a.dist - b.dist);
1161	
1162	    // Cap the per-name follow-up queries. Each survivor triggers a
1163	    // separate `SELECT * FROM nodes WHERE name = ?`; without this cap
1164	    // a project with many similar names (`getUser1`, `getUser2`...)
1165	    // could fan out far beyond `limit` queries before the inner-loop
1166	    // limit kicks in.
1167	    const FUZZY_FOLLOWUP_CAP = Math.max(limit * 2, 50);
1168	    const cappedCandidates = candidates.slice(0, FUZZY_FOLLOWUP_CAP);
1169	
1170	    const results: SearchResult[] = [];
1171	    const seen = new Set<string>();
1172	    for (const c of cappedCandidates) {
1173	      if (results.length >= limit) break;
1174	      let sql = 'SELECT * FROM nodes WHERE name = ?';
1175	      const params: (string | number)[] = [c.name];
1176	      if (kinds && kinds.length > 0) {
1177	        sql += ` AND kind IN (${kinds.map(() => '?').join(',')})`;
1178	        params.push(...kinds);
1179	      }
1180	      if (languages && languages.length > 0) {
1181	        sql += ` AND language IN (${languages.map(() => '?').join(',')})`;
1182	        params.push(...languages);
1183	      }
1184	      sql += ' LIMIT 5';
1185	      const rows = this.db.prepare(sql).all(...params) as NodeRow[];
1186	      for (const row of rows) {
1187	        if (seen.has(row.id)) continue;
1188	        seen.add(row.id);
1189	        // Lower the score for each edit step away from the query so
1190	        // exact-match fallbacks (dist 0) outrank dist-2 typos.
1191	        results.push({ node: rowToNode(row), score: 1 / (1 + c.dist) });
1192	        if (results.length >= limit) break;
1193	      }
1194	    }
1195	    return results;
1196	  }
