1198	  /**
1199	   * FTS5 search with prefix matching
1200	   */
1201	  private searchNodesFTS(query: string, options: SearchOptions): SearchResult[] {
1202	    const { kinds, languages, limit = 100, offset = 0 } = options;
1203	
1204	    // Add prefix wildcard for better matching (e.g., "auth" matches "AuthService", "authenticate")
1205	    // Escape special FTS5 characters and add prefix wildcard.
1206	    //
1207	    // `::` is a qualifier separator in Rust/C++/Ruby, not a token char,
1208	    // so treat it as whitespace before the strip step. Otherwise queries
1209	    // like `stage_apply::run` collapse to `stage_applyrun` (the colons
1210	    // are stripped without splitting) and find nothing. See #173.
1211	    const ftsQuery = query
1212	      .replace(/::/g, ' ') // Rust/C++/Ruby qualifier separator
1213	      .replace(/['"*():^]/g, '') // Remove FTS5 special chars
1214	      .split(/\s+/)
1215	      .filter(term => term.length > 0)
1216	      // Strip FTS5 boolean operators to prevent query manipulation
1217	      .filter(term => !/^(AND|OR|NOT|NEAR)$/i.test(term))
1218	      .map(term => `"${term}"*`) // Prefix match each term
1219	      .join(' OR ');
1220	
1221	    if (!ftsQuery) {
1222	      return [];
1223	    }
1224	
1225	    // BM25 column weights: id=0, name=20, qualified_name=5, docstring=1, signature=2
1226	    // Heavy name weight ensures exact/prefix name matches rank above incidental
1227	    // mentions in long docstrings or qualified names of nested symbols.
1228	    // Fetch 5x requested limit so post-hoc rescoring (kindBonus, pathRelevance,
1229	    // nameMatchBonus) can promote results that BM25 alone undervalues.
1230	    const ftsLimit = Math.max(limit * 5, 100);
1231	
1232	    let sql = `
1233	      SELECT nodes.*, bm25(nodes_fts, 0, 20, 5, 1, 2) as score
1234	      FROM nodes_fts
1235	      JOIN nodes ON nodes_fts.id = nodes.id
1236	      WHERE nodes_fts MATCH ?
1237	    `;
1238	
1239	    const params: (string | number)[] = [ftsQuery];
1240	
1241	    if (kinds && kinds.length > 0) {
1242	      sql += ` AND nodes.kind IN (${kinds.map(() => '?').join(',')})`;
1243	      params.push(...kinds);
1244	    }
1245	
1246	    if (languages && languages.length > 0) {
1247	      sql += ` AND nodes.language IN (${languages.map(() => '?').join(',')})`;
1248	      params.push(...languages);
1249	    }
1250	
1251	    sql += ' ORDER BY score LIMIT ? OFFSET ?';
1252	    params.push(ftsLimit, offset);
1253	
1254	    try {
1255	      const rows = this.db.prepare(sql).all(...params) as (NodeRow & { score: number })[];
1256	      return rows.map((row) => ({
1257	        node: rowToNode(row),
1258	        score: Math.abs(row.score), // bm25 returns negative scores
1259	      }));
1260	    } catch {
1261	      // FTS query failed, return empty
1262	      return [];
1263	    }
1264	  }
