1418	   * Find nodes whose name contains a substring (LIKE-based).
1419	   * Useful for CamelCase-part matching where FTS fails because
1420	   * e.g. "TransportSearchAction" is one FTS token, not matchable by "Search"*.
1421	   *
1422	   * Results are ordered by name length (shorter = more likely to be the core type).
1423	   */
1424	  findNodesByNameSubstring(
1425	    substring: string,
1426	    options: SearchOptions & { excludePrefix?: boolean } = {}
1427	  ): SearchResult[] {
1428	    const { kinds, languages, limit = 30, excludePrefix } = options;
1429	
1430	    let sql = `
1431	      SELECT nodes.*, 1.0 as score
1432	      FROM nodes
1433	      WHERE name LIKE ?
1434	    `;
1435	    const params: (string | number)[] = [`%${substring}%`];
1436	
1437	    // Exclude prefix matches (handled by FTS-based prefix search in Step 2b)
1438	    if (excludePrefix) {
