1588	  /**
1589	   * Distinct file paths that DEPEND ON `filePath`: every file containing a
1590	   * symbol with a cross-file edge (any kind except `contains`) into a symbol
1591	   * of this file. This is the file-level projection of the symbol dependency
1592	   * graph and the basis for blast-radius / `affected` test selection.
1593	   *
1594	   * It deliberately does NOT restrict to `imports` edges. In this graph an
1595	   * `imports` edge connects a file to its own local import declarations
1596	   * (it is always same-file), so an imports-only lookup returns zero
1597	   * cross-file dependents for every file. The real cross-file dependency
1598	   * signal is the resolved call/reference graph — calls, references,
1599	   * instantiates, extends, implements, overrides, type_of, returns,
1600	   * decorates — exactly what {@link GraphTraverser.getImpactRadius} traverses.
1601	   * `contains` is excluded: a parent containing a symbol does not *depend* on
1602	   * it. One indexed query (idx_nodes_file_path + idx_edges_target_kind).
1603	   */
1604	  getDependentFilePaths(filePath: string): string[] {
1605	    const sql = `SELECT DISTINCT src.file_path AS fp
1606	      FROM edges e
1607	      JOIN nodes tgt ON tgt.id = e.target
1608	      JOIN nodes src ON src.id = e.source
1609	      WHERE tgt.file_path = ?
1610	        AND e.kind != 'contains'
1611	        AND src.file_path != ?`;
