2028	   * is (re)written here so rows inserted before the v8 migration get their
2029	   * tail the first time they're attempted.
2030	   */
2031	  markReferencesFailed(refs: Array<{ fromNodeId: string; referenceName: string; referenceKind: string }>): void {
2032	    if (refs.length === 0) return;
2033	    const stmt = this.db.prepare(
2034	      "UPDATE unresolved_refs SET status = 'failed', name_tail = ? WHERE from_node_id = ? AND reference_name = ? AND reference_kind = ?"
2035	    );
2036	    const markMany = this.db.transaction((items: typeof refs) => {
2037	      for (const ref of items) {
2038	        stmt.run(referenceNameTail(ref.referenceName), ref.fromNodeId, ref.referenceName, ref.referenceKind);
2039	      }
2040	    });
2041	    markMany(refs);
