2065	  /**
2066	   * Failed refs whose name tail matches one of the given symbol names — the
2067	   * candidates a sync should retry after files carrying those names changed
2068	   * (#1240). Names matching more than `perNameCeiling` failed refs are
2069	   * skipped entirely: at that population a name is external/builtin noise
2070	   * (`get`, `map`, …) that one new definition won't resolve — the same
2071	   * rationale as resolution's AMBIGUOUS_NAME_CEILING (#999) — and retrying an
2072	   * arbitrary subset would be both wasted work and incoherent coverage.
2073	   */
2074	  getRetryableFailedReferences(names: string[], perNameCeiling: number = 500): UnresolvedReference[] {
2075	    if (names.length === 0) return [];
2076	
2077	    // Pass 1: per-tail counts, chunked under the SQLite parameter limit.
2078	    const retryNames: string[] = [];
2079	    for (let i = 0; i < names.length; i += SQLITE_PARAM_CHUNK_SIZE) {
2080	      const chunk = names.slice(i, i + SQLITE_PARAM_CHUNK_SIZE);
2081	      const placeholders = chunk.map(() => '?').join(',');
2082	      const counts = this.db
2083	        .prepare(
2084	          `SELECT name_tail, COUNT(*) as count FROM unresolved_refs WHERE status = 'failed' AND name_tail IN (${placeholders}) GROUP BY name_tail`
2085	        )
2086	        .all(...chunk) as Array<{ name_tail: string; count: number }>;
2087	      for (const row of counts) {
2088	        if (row.count <= perNameCeiling) retryNames.push(row.name_tail);
2089	      }
2090	    }
2091	    if (retryNames.length === 0) return [];
2092	
2093	    // Pass 2: load the surviving rows.
2094	    const rows: UnresolvedRefRow[] = [];
2095	    for (let i = 0; i < retryNames.length; i += SQLITE_PARAM_CHUNK_SIZE) {
2096	      const chunk = retryNames.slice(i, i + SQLITE_PARAM_CHUNK_SIZE);
2097	      const placeholders = chunk.map(() => '?').join(',');
2098	      const chunkRows = this.db
2099	        .prepare(`SELECT * FROM unresolved_refs WHERE status = 'failed' AND name_tail IN (${placeholders})`)
2100	        .all(...chunk) as UnresolvedRefRow[];
2101	      rows.push(...chunkRows);
2102	    }
2103	
2104	    return rows.map((row) => ({
2105	      fromNodeId: row.from_node_id,
2106	      referenceName: row.reference_name,
2107	      referenceKind: row.reference_kind as EdgeKind,
2108	      line: row.line,
2109	      column: row.col,
2110	      candidates: row.candidates ? safeJsonParse(row.candidates, undefined) : undefined,
2111	      filePath: row.file_path,
2112	      language: row.language as Language,
2113	      rowId: row.id,
2114	    }));
2115	  }
