2117	  /**
2118	   * Distinct node names present in the given files — the symbol names a sync
2119	   * pass uses to look up retryable failed refs after those files changed.
2120	   */
2121	  getNodeNamesByFiles(filePaths: string[]): string[] {
2122	    if (filePaths.length === 0) return [];
2123	    const names = new Set<string>();
2124	    for (let i = 0; i < filePaths.length; i += SQLITE_PARAM_CHUNK_SIZE) {
2125	      const chunk = filePaths.slice(i, i + SQLITE_PARAM_CHUNK_SIZE);
2126	      const placeholders = chunk.map(() => '?').join(',');
